-- Database Table for TER PPh 21 (PP 58 Tahun 2023 / PMK 168 Tahun 2023)
CREATE TABLE IF NOT EXISTS `ter_pph21` (
  `id` INT(11) AUTO_INCREMENT PRIMARY KEY,
  `category` ENUM('A', 'B', 'C') NOT NULL,
  `tier` INT(11) NOT NULL,
  `min_gross` DECIMAL(15,2) NOT NULL,
  `max_gross` DECIMAL(15,2) NOT NULL,
  `rate` DECIMAL(6,4) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

TRUNCATE TABLE `ter_pph21`;

